import { useEffect, useState } from 'react';

export default function FeedLogManager() {
  const [feedLog, setFeedLog] = useState(null);

  useEffect(() => {
    fetch('/api/feedlog')
      .then(response => response.json())
      .then(data => setFeedLog(data));
  }, []);

  return (
    <div>
      {feedLog && (
        <div>
          <h2>FeedLog</h2>
          <ul>
            {feedLog.map(log => (
              <li key={log.id}>
                <h3>{log.title}</h3>
                <p>{log.description}</p>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

